import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, toJob, tx, type JobRow } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const HEARTBEAT_WINDOW_MS = 3000;
const MAX_BODY = 1024 * 1024;
const KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;

interface FieldError { field: string; message: string }

class HttpError extends Error {
  constructor(public status: number, public code: string, message: string, public fields?: FieldError[]) {
    super(message);
  }
}

function send(res: ServerResponse, status: number, body: unknown): void {
  const data = JSON.stringify(body);
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' });
  res.end(data);
}

function sendError(res: ServerResponse, err: HttpError): void {
  const error: Record<string, unknown> = { code: err.code, message: err.message };
  if (err.fields) error.fields = err.fields;
  send(res, err.status, { error });
}

function invalid(fields: FieldError[]): HttpError {
  return new HttpError(400, 'invalid_request', fields.map((f) => `${f.field}: ${f.message}`).join('; ') || 'Invalid request.', fields);
}

const stmts = {
  getById: db.prepare('SELECT * FROM jobs WHERE id = ?'),
  getByKey: db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?'),
  list: db.prepare('SELECT * FROM jobs ORDER BY seq DESC'),
  insert: db.prepare(`INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress, created_at, updated_at, next_run_at, idempotency_key)
    VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, ?, ?)`),
  heartbeat: db.prepare("SELECT beat_at FROM heartbeat WHERE name = 'worker'"),
};

function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (c: Buffer) => {
      size += c.length;
      if (size > MAX_BODY) tooLarge = true;
      else chunks.push(c);
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

function isJsonContentType(ct: string | undefined): boolean {
  if (!ct) return false;
  const type = ct.split(';')[0].trim().toLowerCase();
  return type === 'application/json' || /^application\/[a-z0-9.+-]+\+json$/.test(type);
}

interface Payload { input: string; steps: number; failAttempts: number }

function validateInt(value: unknown, field: string, min: number, max: number, errors: FieldError[]): void {
  if (typeof value !== 'number') errors.push({ field, message: `must be an integer from ${min} to ${max}` });
  else if (!Number.isInteger(value) || value < min || value > max) errors.push({ field, message: `must be an integer from ${min} to ${max}` });
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const errors: FieldError[] = [];
  const keyHeader = req.headers['idempotency-key'];
  let key: string | undefined;
  if (keyHeader !== undefined) {
    const k = Array.isArray(keyHeader) ? keyHeader.join(',') : keyHeader;
    if (!KEY_RE.test(k)) errors.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
    else key = k;
  }

  const raw = await readBody(req);
  let payload: Payload | undefined;
  if (!isJsonContentType(req.headers['content-type'])) {
    errors.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else if (raw === null) {
    errors.push({ field: 'body', message: 'body is too large' });
  } else {
    let body: unknown;
    let parsed = true;
    try {
      body = JSON.parse(raw);
    } catch {
      parsed = false;
      errors.push({ field: 'body', message: 'body must be valid JSON' });
    }
    if (parsed) {
      if (typeof body !== 'object' || body === null || Array.isArray(body)) {
        errors.push({ field: 'body', message: 'body must be a JSON object' });
      } else {
        const obj = body as Record<string, unknown>;
        const before = errors.length;
        for (const k of Object.keys(obj)) {
          if (k !== 'input' && k !== 'steps' && k !== 'failAttempts') errors.push({ field: k, message: 'unknown field' });
        }
        const input = obj.input;
        if (!Object.hasOwn(obj, 'input')) errors.push({ field: 'input', message: 'is required' });
        else if (typeof input !== 'string') errors.push({ field: 'input', message: 'must be a string' });
        else if (input.length < 1 || input.length > 1000) errors.push({ field: 'input', message: 'must be 1 to 1000 characters' });
        else if (input.trim().length === 0) errors.push({ field: 'input', message: 'must not be only whitespace' });
        const steps = Object.hasOwn(obj, 'steps') ? obj.steps : 5;
        const failAttempts = Object.hasOwn(obj, 'failAttempts') ? obj.failAttempts : 0;
        validateInt(steps, 'steps', 1, 20, errors);
        validateInt(failAttempts, 'failAttempts', 0, 5, errors);
        if (errors.length === before) payload = { input: input as string, steps: steps as number, failAttempts: failAttempts as number };
      }
    }
  }
  if (errors.length > 0 || !payload) throw invalid(errors);
  const p = payload;

  const result = tx(db, () => {
    if (key !== undefined) {
      const existing = stmts.getByKey.get(key) as JobRow | undefined;
      if (existing) {
        if (existing.input === p.input && existing.steps === p.steps && existing.fail_attempts === p.failAttempts) {
          return { status: 200, row: existing };
        }
        throw new HttpError(409, 'idempotency_conflict', 'Idempotency-Key was already used with a different payload.');
      }
    }
    const id = randomUUID();
    const now = new Date().toISOString();
    stmts.insert.run(id, p.input, p.steps, p.failAttempts, now, now, Date.now(), key ?? null);
    return { status: 201, row: stmts.getById.get(id) as unknown as JobRow };
  });
  send(res, result.status, toJob(result.row));
}

function methodNotAllowed(allowed: string[]): HttpError {
  return new HttpError(405, 'method_not_allowed', `Method not allowed. Allowed: ${allowed.join(', ')}.`);
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  let pathname: string;
  try {
    pathname = new URL(req.url ?? '/', 'http://localhost').pathname;
  } catch {
    throw new HttpError(404, 'not_found', 'Not found.');
  }
  const method = req.method ?? 'GET';

  if (pathname === '/') {
    if (method !== 'GET') throw methodNotAllowed(['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/health') {
    if (method !== 'GET') throw methodNotAllowed(['GET']);
    const row = stmts.heartbeat.get() as { beat_at: number } | undefined;
    const up = !!row && Date.now() - row.beat_at <= HEARTBEAT_WINDOW_MS;
    return send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') {
      const rows = stmts.list.all() as unknown as JobRow[];
      return send(res, 200, { jobs: rows.map(toJob) });
    }
    if (method === 'POST') return createJob(req, res);
    throw methodNotAllowed(['GET', 'POST']);
  }
  const m = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (m) {
    if (method !== 'GET') throw methodNotAllowed(['GET']);
    let id: string;
    try {
      id = decodeURIComponent(m[1]);
    } catch {
      throw new HttpError(404, 'not_found', 'Job not found.');
    }
    const row = stmts.getById.get(id) as JobRow | undefined;
    if (!row) throw new HttpError(404, 'not_found', 'Job not found.');
    return send(res, 200, toJob(row));
  }
  throw new HttpError(404, 'not_found', 'Not found.');
}

const port = Number(process.env.PORT || 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((err: unknown) => {
    if (res.headersSent) {
      res.destroy();
      return;
    }
    if (err instanceof HttpError) return sendError(res, err);
    console.error(err);
    sendError(res, new HttpError(500, 'internal_error', 'Internal server error.'));
  });
});
server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  server.close(() => {
    try { db.close(); } catch { /* ignore */ }
    process.exit(0);
  });
  server.closeAllConnections();
  setTimeout(() => process.exit(0), 3000).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

